static void virtqueue_map_desc(unsigned int *p_num_sg, hwaddr *addr, struct iovec *iov,
                               unsigned int max_num_sg, bool is_write,
                               hwaddr pa, size_t sz)
{
     unsigned num_sg = *p_num_sg;
     assert(num_sg <= max_num_sg);

     while (sz) {
         hwaddr len = sz;
        iov[num_sg].iov_base = cpu_physical_memory_map(pa, &len, is_write);
        iov[num_sg].iov_len = len;
        addr[num_sg] = pa;

        sz -= len;
        pa += len;
        num_sg++;
    }
    *p_num_sg = num_sg;
}

bool ParseNewStyleVp9CodecID(const std::string& codec_id,
VideoCodecProfile* profile,
uint8_t* level_idc,
                             gfx::ColorSpace::TransferID* eotf) {
// Initialize optional fields to their defaults.
  *eotf = gfx::ColorSpace::TransferID::BT709;

std::vector<std::string> fields = base::SplitString(
codec_id, ".", base::KEEP_WHITESPACE, base::SPLIT_WANT_ALL);

// First four fields are mandatory. No more than 9 fields are expected.
if (fields.size() < 4 || fields.size() > 9) {
DVLOG(3) << __func__ << " Invalid number of fields (" << fields.size()
<< ")";
return false;
}

if (fields[0] != "vp09") {
DVLOG(3) << __func__ << " Invalid 4CC (" << fields[0] << ")";
return false;
}

std::vector<int> values;
for (size_t i = 1; i < fields.size(); ++i) {
// Missing value is not allowed.
if (fields[i] == "") {
DVLOG(3) << __func__ << " Invalid missing field (position:" << i << ")";
return false;
}
int value;
if (!base::StringToInt(fields[i], &value) || value < 0) {
DVLOG(3) << __func__ << " Invalid field value (" << value << ")";
return false;
}
values.push_back(value);
}

const int profile_idc = values[0];
switch (profile_idc) {
case 0:
*profile = VP9PROFILE_PROFILE0;
break;
case 1:
*profile = VP9PROFILE_PROFILE1;
break;
case 2:
*profile = VP9PROFILE_PROFILE2;
break;
case 3:
*profile = VP9PROFILE_PROFILE3;
break;
default:
DVLOG(3) << __func__ << " Invalid profile (" << profile_idc << ")";
return false;
}

*level_idc = values[1];
switch (*level_idc) {
case 1:
case 11:
case 2:
case 21:
case 3:
case 31:
case 4:
case 41:
case 5:
case 51:
case 52:
case 6:
case 61:
case 62:
break;
default:
DVLOG(3) << __func__ << " Invalid level (" << *level_idc << ")";
return false;
}

const int bit_depth = values[2];
if (bit_depth != 8 && bit_depth != 10 && bit_depth != 12) {
DVLOG(3) << __func__ << " Invalid bit-depth (" << bit_depth << ")";
return false;
}

if (values.size() < 4)
return true;
  const int color_primaries = values[3];
  // TODO(chcunningham): parse and bubble up color primaries, described in ISO
  // 23001-8:2016 Table 2.
  // Values 0, 3, and 23 - 255 are reserved.
  if (color_primaries == 0 || color_primaries == 3 || color_primaries > 22) {
    DVLOG(3) << __func__ << " Invalid color primaries (" << color_primaries
             << ")";
return false;
}

if (values.size() < 5)
return true;
  if (!ParseVp9Eotf(values[4], eotf)) {
DVLOG(3) << __func__ << " Invalid transfer function (" << values[4] << ")";
return false;
}

  // TODO(chcunningham): Parse and bubble up the following fields. For now just
  // doing basic validation.
if (values.size() < 6)
return true;
  const int matrix_coefficients = values[5];
  if (matrix_coefficients > 11) {
    DVLOG(3) << __func__ << " Invalid matrix coefficients ("
             << matrix_coefficients << ")";
return false;
}

if (values.size() < 7)
return true;
const int video_full_range_flag = values[6];
if (video_full_range_flag > 1) {
DVLOG(3) << __func__ << " Invalid full range flag ("
<< video_full_range_flag << ")";
return false;
}

if (values.size() < 8)
return true;
const int chroma_subsampling = values[7];
if (chroma_subsampling > 3 ||
      (chroma_subsampling != 3 && matrix_coefficients == 0)) {
DVLOG(3) << __func__ << " Invalid chroma subsampling ("
<< chroma_subsampling << ")";
return false;
}

return true;
}

dissect_ac_if_hdr_body(tvbuff_t *tvb, gint offset, packet_info *pinfo _U_,
        proto_tree *tree, usb_conv_info_t *usb_conv_info)
{
    gint     offset_start;
    guint16  bcdADC;
    guint8   ver_major;
    double   ver;
    guint8   if_in_collection, i;
    audio_conv_info_t *audio_conv_info;


    offset_start = offset;

    bcdADC = tvb_get_letohs(tvb, offset);
    ver_major = USB_AUDIO_BCD44_TO_DEC(bcdADC>>8);
    ver = ver_major + USB_AUDIO_BCD44_TO_DEC(bcdADC&0xFF) / 100.0;

    proto_tree_add_double_format_value(tree, hf_ac_if_hdr_ver,
            tvb, offset, 2, ver, "%2.2f", ver);
    audio_conv_info = (audio_conv_info_t *)usb_conv_info->class_data;
     if(!audio_conv_info) {
         audio_conv_info = wmem_new(wmem_file_scope(), audio_conv_info_t);
         usb_conv_info->class_data = audio_conv_info;
         /* XXX - set reasonable default values for all components
            that are not filled in by this function */
     }
     audio_conv_info->ver_major = ver_major;
     offset += 2;

    /* version 1 refers to the Basic Audio Device specification,
       version 2 is the Audio Device class specification, see above */
    if (ver_major==1) {
        proto_tree_add_item(tree, hf_ac_if_hdr_total_len,
                tvb, offset, 2, ENC_LITTLE_ENDIAN);
        offset += 2;
        if_in_collection = tvb_get_guint8(tvb, offset);
        proto_tree_add_item(tree, hf_ac_if_hdr_bInCollection,
                tvb, offset, 1, ENC_LITTLE_ENDIAN);
        offset++;

        for (i=0; i<if_in_collection; i++) {
            proto_tree_add_item(tree, hf_ac_if_hdr_if_num,
                    tvb, offset, 1, ENC_LITTLE_ENDIAN);
            offset++;
        }
    }

    return offset-offset_start;
}

