static MagickBooleanType WritePICTImage(const ImageInfo *image_info,
Image *image)
{
#define MaxCount  128
#define PictCropRegionOp  0x01
#define PictEndOfPictureOp  0xff
#define PictJPEGOp  0x8200
#define PictInfoOp  0x0C00
#define PictInfoSize  512
#define PictPixmapOp  0x9A
#define PictPICTOp  0x98
#define PictVersion  0x11

const StringInfo
*profile;

double
x_resolution,
y_resolution;

MagickBooleanType
status;

MagickOffsetType
offset;

PICTPixmap
pixmap;

PICTRectangle
bounds,
crop_rectangle,
destination_rectangle,
frame_rectangle,
size_rectangle,
source_rectangle;

register const IndexPacket
*indexes;

register const PixelPacket
*p;

register ssize_t
i,
x;

size_t
bytes_per_line,
count,
row_bytes,
storage_class;

ssize_t
y;

unsigned char
*buffer,
*packed_scanline,
*scanline;


unsigned short
base_address,
transfer_mode;

/*
Open output image file.
*/
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickSignature);
if (image->debug != MagickFalse)
